use std::fs

fn main() {
    let limit = 200000
    let mut sieve: Vec<bool> = []
    for i in 0..(limit + 1) {
        sieve.push(true)
    }
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut c = 0
    let mut last = 0
    for i in 0..(limit + 1) {
        if i >= 2 && sieve[i] {
            c += 1
            last = i
            let mut j = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        counts.push(c)
        largest.push(last)
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = s.parse().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

